#!/usr/bin/env python3
"""Generate deterministic Phase 3.1 editorial fixtures and assembled outputs."""

from __future__ import annotations

import base64
import json
import sys
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from pipeline.briefing_assembler import build_briefing, render_markdown  # noqa: E402
from pipeline.editorial_scoring import load_weights, score_pool  # noqa: E402

PAYLOAD = """"""


def write_json(path: Path, value: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(value, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )


def main() -> int:
    pool = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)).decode("utf-8"))
    weights = load_weights(ROOT / "config/editorial-weights.json")
    scores = score_pool(pool, weights)
    briefing = build_briefing(pool, scores, weights)

    examples = ROOT / "data/examples"
    write_json(examples / "candidate-pool.example.json", pool)
    write_json(examples / "editorial-scores.example.json", scores)
    write_json(examples / "briefing-assembled.example.json", briefing)
    (examples / "briefing-assembled.example.md").write_text(
        render_markdown(briefing) + "\n",
        encoding="utf-8",
    )
    print("PASS generated Phase 3.1 editorial examples")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
